    """Even row pattern: 4s at positions 0, 2, 3-5, 7-9, 10-11"""
    return [4 if c in [0, 2, 3, 4, 5, 7, 8, 9, 10, 11] else 0 for c in range(12)]

def state_b(row_num):
    """Odd row pattern: 4s at positions 0, 2, 7, 8, 10-11"""
